"""End-to-end test of the generate -> verify -> retry loop with a stub backend."""

from __future__ import annotations

from pathlib import Path

import pytest

import testing_agent.generate.generator as generator_module
from testing_agent.generate.backends import Backend, GenerationError
from testing_agent.generate.generator import generate_tests
from testing_agent.generate.models import GenerationTarget

FAILING_TEST = '''\
"""Generated by stub backend (round 1 - intentionally failing)."""
import pytest
import calc

def test_add():
    assert calc.add(1, 2) == 99
'''

PASSING_TEST = '''\
"""Generated by stub backend (round 2)."""
import calc

def test_add():
    assert calc.add(1, 2) == 3

def test_multiply():
    assert calc.multiply(2, 3) == 6
'''


class StubBackend(Backend):
    """Generates a failing suite first, a passing one after feedback."""

    id = "stub"

    def __init__(self) -> None:
        self.calls: list[str | None] = []

    def is_available(self) -> bool:
        return True

    def generate(
        self,
        root: Path,
        target: GenerationTarget,
        framework: str,
        timeout_seconds: int,
        failure_feedback: str | None = None,
    ) -> str:
        self.calls.append(failure_feedback)
        if failure_feedback is None:
            return FAILING_TEST
        return PASSING_TEST


def build_gap_project(tmp_path: Path) -> None:
    (tmp_path / "pyproject.toml").write_text(
        '[project]\nname = "p"\n[dependency-groups]\ndev = ["pytest>=8"]\n', encoding="utf-8"
    )
    (tmp_path / "calc.py").write_text(
        "def add(a, b):\n    return a + b\n\n\ndef multiply(a, b):\n    return a * b\n",
        encoding="utf-8",
    )
    (tmp_path / "tests").mkdir()


def test_full_loop_retries_after_failure_and_passes(tmp_path: Path) -> None:
    build_gap_project(tmp_path)
    stub = StubBackend()
    original = generator_module.select_backend

    def fake_select(explicit=None):
        if explicit in (None, "auto"):
            return stub
        return original(explicit)

    generator_module.select_backend = fake_select
    try:
        report = generate_tests(tmp_path, backend_id="auto", max_files=1, feedback_rounds=2)
    finally:
        generator_module.select_backend = original

    assert report.backend == "stub"
    assert len(report.outcomes) == 1
    outcome = report.outcomes[0]
    assert outcome.success is True
    assert outcome.rounds == 2  # failed round 1, passed round 2
    # The failure feedback from round 1 must have reached round 2
    assert stub.calls[0] is None
    assert stub.calls[1] is not None and "test_add" in stub.calls[1]

    generated = Path(outcome.test_file)
    assert generated.is_file()
    assert "multiply" in generated.read_text(encoding="utf-8")


def test_backend_error_returns_failed_outcome(tmp_path: Path) -> None:
    build_gap_project(tmp_path)

    class ExplodingBackend(StubBackend):
        id = "exploding"

        def generate(self, *args, **kwargs):
            raise GenerationError("boom")

    stub = ExplodingBackend()
    original = generator_module.select_backend
    generator_module.select_backend = lambda explicit=None: stub
    try:
        report = generate_tests(tmp_path, backend_id="auto", max_files=1)
    finally:
        generator_module.select_backend = original

    assert report.outcomes[0].success is False
    assert report.outcomes[0].error == "boom"


def test_cli_generate_manifest_mode(tmp_path: Path) -> None:
    """The manifest path writes gap-manifest.md deterministically."""
    from testing_agent.generate.generator import ManifestBackend, write_generation_report
    from testing_agent.generate.models import GenerationReport

    build_gap_project(tmp_path)
    report = GenerationReport(
        backend="manifest",
        outcomes=[],
        manifest_path=str(tmp_path / ".testing-agent" / "gap-manifest.md"),
    )
    write_generation_report(tmp_path, report)
    assert Path(report.manifest_path).with_suffix(".md").name == "gap-manifest.md"


def test_stub_backend_never_available_as_explicit_unknown() -> None:
    with pytest.raises(KeyError):
        generator_module.select_backend("stub")
